		["{npc:837}, the priest trainer"] = "{npc:837}，牧師訓練師",
		["{npc:8416}, at the door on the way out; inside"] = "{npc:8416}，在出門處的門口；室內",
		["{npc:8416}, by the door of {area:77}; inside"] = "{npc:8416}，在{area:77}門口；室內",
		["{npc:8508}, on the dock"] = "{npc:8508}，在碼頭上",
		["{npc:912}, the warrior trainer"] = "{npc:912}，戰士訓練師",
		["{npc:916}, the rogue trainer"] = "{npc:916}，盜賊訓練師",
		["{npc:944}, the mage trainer, inside {area:77}"] = "{npc:944}，法師訓練師，在{area:77}裡面",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}，在{object:171524}的郵箱旁",
		["{quest:1688}: her choker and The Binding are on {zone:1436}'s east-Elwynn loop"] = "{quest:1688}：她的項圈和「束縛」在{zone:1436}的艾爾文東部環線上",
		["{zone:1426}: kill these as you meet them"] = "{zone:1426}：沿途遇到就擊殺",
		["{zone:1453} flight master"] = "{zone:1453}飛行管理員",
} end)()
t.guides["forever/alliance/human/01-elwynn-forest"] = (function() return {
		["\"Auntie\" Bernice Stonefield"] = "波尼斯·斯通菲爾德姑媽",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "回到{npc:6122}那裡。在{object:2164}地下室的召喚法陣使用{item:6928}，擊敗被召喚出的虛空行者。",
		["Back to {zone:1429}"] = "返回{zone:1429}",
		["Billy plays in the {area:64}, east of the mine."] = "比利在礦坑東邊的{area:64}玩耍。",
		["Chunks of Boar Meat"] = "大塊野豬肉",
		["Class trainer"] = "職業訓練師",
		["Crystal Kelp Fronds"] = "水晶藻葉",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore.\nCareful: the Rogue Wizards cast from range and a {npc:6866} (10) walks the shore with them: pull them one at a time."] = "迪菲亞流浪巫師在{area:86}岸邊紮營；他們也會掉落紅色亞麻面罩。{object:56}在東北岸的魚人村裡。\n小心：流浪巫師會遠程施法，還有一名{npc:6866}（10級）跟著他們在岸邊走動：一次拉一隻。",
		["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "迪菲亞暴徒在修道院東邊的空地及山谷東側紮營。",
		["Druid trainer"] = "德魯伊訓練師",
		["Follow the hills south to the tower, on the road west."] = "沿著山丘向南走到塔，在往西的路上。",
		["Follow the hills south to the tower."] = "沿著山丘向南走到塔。",
		["Follow the path north to the mine. Kobold Workers swarm outside it; every kobold in the valley can drop the {object:83763}.\nNow and then a kobold here drops a {quest:91741}: right-click it and hand it to {npc:951} on your next Abbey stop."] = "沿小路向北前往礦坑。狗頭人工人（{npc:257}）聚集在坑外；山谷裡的每個狗頭人都可能掉落{object:83763}。\n這裡的狗頭人偶爾會掉落{quest:91741}：右鍵點擊它，下次回修道院時交給{npc:951}。",
		["Follow the road east past the {area:91} to the bridge. Finish the Prowlers and Young Forest Bears around the river south of it."] = "沿著道路向東經過{area:91}走到橋邊。在橋南邊的河流周圍殺完覓食的灰狼和小森林熊。",
		["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "沿著道路從{area:87}向北進入{zone:1453}。{npc:5497}站在{object:2101}的高塔裡；她會給你一個瓶子，用於{quest:1861}瀑布。",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "沿著道路從{area:87}向北進入{zone:1453}。{npc:6122}在{object:2101}的{object:2164}地下室等候。",
		["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "沿著道路向南離開{area:87}，前往{area:64}。{npc:251}在房子旁等候。",
		["Follow the road south to the {area:120}, on the way into {zone:1436}. {npc:963} stands outside the barracks; {npc:955} stands inside. He has {quest:91738} only while you carry the {item:247824}: talk to him and it goes straight to the hand-in."] = "沿道路向南到{area:120}，就在進入{zone:1436}的路上。{npc:963}站在兵營外；{npc:955}站在裡面。只有你帶著{item:247824}時他才會給{quest:91738}：和他交談後就直接進入交付環節。",
		["Follow the road west back to {area:87}; {npc:6306} stands on the lake shore before town. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "沿路向西回到{area:87}；{npc:6306}站在進城前的湖岸上。{npc:377}（牧師）、{npc:328}（法師）和{npc:917}（盜賊）站在旅店樓上：從裡面上樓，箭頭分不清樓層。",
		["From level 5 {npc:248362}, a level 3 elite, is two levels under you: he waits down the second turn on the right inside the mine.\nCareful: clear the Laborers around him first and fight him at full health."] = "從5級起，3級精英{npc:248362}比你低兩級：他在礦坑內右手第二個拐角處等著。\n小心：先清掉他周圍的苦工，滿血再和他戰鬥。",
		["From level 5: Kelsey's {quest:91752}. {npc:248362} (3, elite) is two levels under you then."] = "從5級起：凱爾希的{quest:91752}。那時{npc:248362}（3，精英）比你低兩級。",
		["Fun with Elementals: {npc:248464}"] = "快樂玩元素：{npc:248464}",
		["He stands by the river west of the farm."] = "他站在農場西邊的河邊。",
		["Head back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "穿過{area:87}返回，沿路向東到{area:62}。{npc:881}（9級）站在農舍旁。",
		["Head east out of {area:87} along the lake shore. {npc:383} stands on the shore north-east of town."] = "沿湖岸往東離開{area:87}。{npc:383}站在鎮子東北的岸上。",
		["Heal and fortify {npc:12423}"] = "治療並強化{npc:12423}",
		["If you skipped {quest:91740}, grind here to level 8.85 to stay on the route's plan."] = "如果你跳過了{quest:91740}，在這裡刷到8.85級以跟上路線計劃。",
		["If you skipped {quest:91775}, grind here to level 8.39 to stay on the route's plan."] = "如果你跳過了{quest:91775}，在這裡刷到8.39級以跟上路線計劃。",
		["Inside"] = "在裡面",
		["Inside {area:34}"] = "{area:34}內部",
		["It lies by the river north-west of the logging camp."] = "它躺在伐木場西北方的河邊。",
		["Kobold Laborers work the tunnels inside the mine. {npc:248362} waits down the second turn on the right.\nNow and then a Laborer drops a {quest:91741}: right-click it and hand it to {npc:951} at the Abbey after the mine.\nCareful: {npc:248362} (3) is elite: below level 5, leave him be."] = "狗頭人苦工（{npc:80}）在礦坑的隧道裡幹活。{npc:248362}在右手第二個拐角處等著。\n苦工偶爾會掉落{quest:91741}：右鍵點擊它，離開礦坑後在修道院交給{npc:951}。\n小心：{npc:248362}（3）是精英：5級之前別惹他。",
		["Large Candles"] = "大蠟燭",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "從正門離開{zone:1453}。{quest:1861}瀑布在城門西南方，位於往西前往{zone:1436}的路上：在瀑布底部裝滿{item:7207}。",
		["Level 8.39"] = "等級 8.39",
		["Level 8.85"] = "等級 8.85",
		["Lost Books: Kobold Miners and Tunnelers"] = "遺失的書：狗頭人礦工和狗頭人隧道工",
		["Mages: {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "法師：法師訓練師{npc:198}在修道院樓上：從裡面的樓梯上去，箭頭無法區分樓層。",
		["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp. Careful: the murlocs stand close together, so a fight easily pulls two or three at once: pull them one at a time from the edge of the camp, and don't chase one into the next group."] = "魚人和魚人士兵佔據東岸；垃圾堆在牠們的營地裡。小心：魚人站得很近，一場戰鬥很容易同時引來兩三隻：從營地邊緣一次拉一隻，也不要追著一隻跑進下一群。",
		["North-east of the logging camp. Defias Rogue Wizards camp on the shores of the lake.\nCareful: the Rogue Wizards cast from range and a {npc:6866} (10) walks the shore with them: pull them one at a time."] = "在伐木營地東北方。迪菲亞流浪巫師在湖岸邊紮營。\n小心：流浪巫師會遠程施法，還有一名{npc:6866}（10級）跟著他們在岸邊走動：一次拉一隻。",
		["Painted Gnoll Armbands"] = "彩色豺狼人臂章",
		["Red Burlap Bandanas"] = "紅色粗麻面罩",
		["Red Linen Bandanas"] = "紅色亞麻面罩",
		["Riverpaw Runts and Outrunners hold the hills south of the garrison, along the {zone:1436} border."] = "矮小的河爪豺狼人和河爪豺狼人前鋒佔據要塞南邊、沿著{zone:1436}邊界的山丘。",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "河爪豺狼人在{area:86}西邊的山丘紮營；{quest:91725}就在他們的營地裡。",
		["Shaman trainer"] = "薩滿訓練師",
		["She stands by her cart at the vineyard east of the Abbey."] = "她站在修道院東邊葡萄園的推車旁。",
		["She stands outside the mine entrance. Her next errand, {quest:91752}, sends you after {npc:248362} inside, a level 3 elite: the guide gives it from level 5, when he is two levels under you."] = "她站在礦坑入口外。她的下一個差事{quest:91752}會派你進去對付3級精英{npc:248362}：指南從5級起給出這個任務，那時他比你低兩級。",
		["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "新鮮的紅蘋果，向{npc:894}取得，用於{quest:91736}",
		["Sit (/sit) by his campfire until you have {spell:1229451}"] = "在他的營火旁坐下（/sit），直到獲得{spell:1229451}",
		["South down the road to the {area:64}."] = "沿著道路向南前往{area:64}。",
		["Subdue the voidwalker"] = "制服虛空行者",
		["Tame {npc:1922}"] = "馴服{npc:1922}",
		["Tame {npc:524}"] = "馴服{npc:524}",
		["Tame {npc:822}"] = "馴服{npc:822}",
		["The Defias camp"] = "迪菲亞營地",
		["The Fishing Traps sit along the west shore of the lake."] = "捕魚陷阱沿著湖的西岸分布。",
		["The Stonefield farm is west of the mine. Ma and \"Auntie\" Bernice stand by the house.\nShe sits inside the farmhouse."] = "斯通菲爾德農場在礦坑西邊。斯通菲爾德媽媽和波尼斯·斯通菲爾德姑媽站在房子旁。\n她坐在農舍裡面。",
		["The bridge"] = "橋",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it.\nCareful: Elmpaw, a level 12 elite gnoll, walks the woods and hills from the logging camp north to {area:86} and the gnoll camps: keep clear of him when you see him coming."] = "營地在橋的東北方。成捆的木材散落在營地周圍和營地北邊的樹林裡。\n小心：12級精英豺狼人榆爪在樹林和山丘間遊蕩，從伐木營地往北一直到{area:86}和豺狼人營地：看到他過來就避開。",
		["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "裝葡萄的箱子在迪菲亞後方的葡萄園裡。{npc:103}在山谷東端的小屋旁等候。",
		["The gnoll camps"] = "豺狼人營地",
		["The kobold camp"] = "狗頭人營地",
		["The lake shore"] = "湖岸",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels.\nCareful: {npc:471} (7-10), the Mine Spiders (7-9) and {npc:248474} (7) are elites deep in the mine: pull the kobolds one at a time near the entrance and back out if an elite comes; they're easier with a friend."] = "礦坑在豺狼人營地西南方。{item:247816}散落在入口附近；隧道裡是狗頭人地卜師。\n小心：{npc:471}（7-10級）、礦坑蜘蛛（7-9級）和{npc:248474}（7級）都是礦坑深處的精英：在入口附近一次拉一隻狗頭人，若有精英過來就退出去；有朋友同行會輕鬆些。",
		["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "礦坑在葡萄園西邊。狗頭人礦工和狗頭人隧道工遍布上下兩層；有名字的狗頭人{npc:248464}拿著圖畫書，在下層隧道裡。{npc:248464}是精英：建議組隊。",
		["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too.\nCareful: {npc:276180}, a level 11 rare murloc, walks the river by {npc:261}' bridge, east of the Prowlers' woods: leave him be."] = "東岸的魚人會掉落海藻。剝皮者：森林灰狼在湖與{area:91}之間的樹林遊蕩；更東邊的覓食的灰狼也能剝下毛皮。\n小心：11級稀有魚人{npc:276180}在{npc:261}的橋邊河裡走動，在覓食的灰狼所在樹林的東邊：別去惹他。",
		["The vineyards and {npc:103}"] = "葡萄園與{npc:103}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["The {item:247813}, Axe and Toolbox lie in the river south of the bridge. {npc:330}, a big boar, roots in the {area:62} west of the river with her {npc:390}: pull the piglets away first. Kill Young Forest Bears on the way; the Prowlers (level 9-10) wait for the walk back to {npc:261}, after the logging camp and the mine. Careful: {npc:248278} is a level 11 elite on the murloc shore. Only go for his head with a group; otherwise leave him: it's optional."] = "{item:247813}、浸水的斧頭和浸水的工具箱在橋南邊的河裡。{npc:330}是一頭大野豬，和她的{npc:390}在河西邊的{area:62}拱土：先把小豬引開。沿途擊殺小森林熊；覓食的灰狼（9-10級）留到伐木場和礦坑之後、走回{npc:261}的路上再打。小心：{npc:248278}是魚人海岸上的11級精英。只有組隊才去拿他的頭；否則別理他：這是可選的。",
		["The {quest:91736}"] = "{quest:91736}",
		["The {quest:91736} stands north of the {area:120}. Click it with four Shiny Red Apples in your bags: it takes them and gives you a {item:247824} on the spot (the quest never shows in your quest log). Keep the Applejack for {npc:955}: don't drink it."] = "{quest:91736}立在{area:120}以北。帶著四個閃光紅蘋果點選它：它會收下蘋果，並當場交給你一個{item:247824}（該任務不會出現在任務日誌中）。把蘋果酒留給{npc:955}：不要喝掉。",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:248464} (level 6 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "這些是精英怪：建議組隊，找人一起做。{npc:248464}（6級精英）需要2人小隊。如果你獨自一人就跳過：路線會讓你把經驗刷回來。",
		["Walk into the mine"] = "走進礦坑",
		["Walk through the mine"] = "穿過礦坑",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "順便：向{npc:11867}（{object:2096}，10銀幣）學習法杖；升級期間，法杖提供的法術屬性比單手武器多。",
		["Wolves"] = "狼",
		["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "你從修道院前開始。{npc:823}站在台階下，{npc:197}在大廳裡，{npc:951}和{npc:247229}在右側的圖書室，{npc:196}在修道院西北角外。",
		["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "幼狼和森林狼在修道院周圍的田野遊蕩。",
		["grind on {npc:1922}"] = "刷{npc:1922}",
		["grind on {npc:40}"] = "刷{npc:40}",
		["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "他的狗頭人追蹤器會標出通往{area:87}路上可點擊的狗頭人",
		["talk to the trainer"] = "與訓練師交談",
		["{area:18}: kill these as you meet them"] = "{area:18}：遇到就殺",
		["{area:34}: kill these as you meet them"] = "{area:34}：遇到就殺",
		["{area:54}: kill these as you meet them"] = "{area:54}：遇到就殺",
		["{area:64}: kill these as you meet them"] = "{area:64}：遇到就殺",
		["{item:247824}, from the still"] = "{item:247824}，來自蒸餾器",
		["{item:286215}: Stonetusk Boars"] = "{item:286215}：石牙野豬",
		["{item:6785}: the {object:83763} in the Defias camp"] = "{item:6785}：迪菲亞營地裡的{object:83763}",
		["{item:981}; below ground"] = "{item:981}；在地下",
		["{npc:11026} takes it once your {skill:202} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:202}技能達到20時，{npc:11026}會接收它：在此之前採集或製作，指南同時繼續進行。",
		["{npc:1103} takes it once your {skill:197} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:197}技能達到20時，{npc:1103}會接收它：在此之前採集或製作，指南同時繼續進行。",
		["{npc:1103}, at the logging camp"] = "{npc:1103}，在伐木場",
		["{npc:11068} takes it once your {skill:333} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:333}技能達到20時，{npc:11068}會接收它：在此之前採集或製作，指南同時繼續進行。",
		["{npc:1215} takes it once your {skill:171} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:171}技能達到20時，{npc:1215}會接收它：在此之前採集或製作，指南同時繼續進行。",
		["{npc:1215}, beside {npc:1218}"] = "{npc:1215}，在{npc:1218}旁邊",
		["{npc:1218} takes it once your {skill:182} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:182}技能達到20時，{npc:1218}會接收它：在此之前採集或製作，指南同時繼續進行。",
		["{npc:1218}, north of {area:87}"] = "{npc:1218}，在{area:87}以北",
		["{npc:12423} kneels wounded by a tree on the west shore of {area:18}, among the Fishing Traps. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count. He walks off once both land and is back in about 3 minutes."] = "{npc:12423}受傷跪在{area:18}西岸的一棵樹旁，就在捕魚陷阱之間。對他施放{spell:613}（等級2），然後施放{spell:1243}：等級1的{spell:613}不算數。兩個法術都生效後他會離開，大約3分鐘後回來。",
		["{npc:1430} cooks in the inn's kitchen. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:1430}在旅店廚房裡做飯。{npc:377}（牧師）、{npc:328}（法師）和{npc:917}（盜賊）在旅店樓上：走室內樓梯上去，箭頭無法區分樓層。",
		["{npc:1430}: Camping 101 asks you to learn it; below ground"] = "{npc:1430}：野營入門要求你學會它；在地下",
		["{npc:1632} takes it once your {skill:165} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:165}技能達到20後，{npc:1632}就會接收它：在那之前先採集或製作，指南會同時繼續進行。",
		["{npc:1632}, beside {npc:6306}"] = "{npc:1632}，在{npc:6306}旁邊",
		["{npc:1651} takes it once your {skill:356} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:356}技能達到20後，{npc:1651}就會接收它：在那之前先採集或製作，指南會同時繼續進行。",
		["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922}：用{item:15908}馴服牠",
		["{npc:197}, inside"] = "{npc:197}，在裡面",
		["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}，法師訓練師，在修道院內",
		["{npc:2329} takes it once your {skill:129} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:129}技能達到20後，{npc:2329}就會接收它：在那之前先採集或製作，指南會同時繼續進行。",
		["{npc:2329}, in the Lion's Pride Inn"] = "{npc:2329}，在獅王之傲旅店裡",
		["{npc:240}, while William brews"] = "{npc:240}，趁威廉釀酒時",
		["{npc:247226}, outside the mine"] = "{npc:247226}，在礦坑外",
		["{npc:247229}, in the library; inside"] = "{npc:247229}，在圖書室；在裡面",
		["{npc:248242} and {npc:248248} stand at the foot of the tower."] = "{npc:248242}和{npc:248248}站在塔底。",
		["{npc:248278} is a level 11 elite on the murloc shore south of the bridge: grouping up is encouraged, look for people to do it with. {quest:91740} needs a group of 2. Skip it if you are alone: the route has you grind the XP back. Right-click the head for its quest."] = "{npc:248278}是橋南邊魚人河岸上的11級精英：建議組隊，找人一起做。{quest:91740}需要2人小隊。如果你獨自一人就跳過：路線會讓你把經驗刷回來。右鍵點選它的頭接取任務。",
		["{npc:248415} stands behind the Abbey, by the stables. {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:248415}站在修道院後面的馬廄旁。法師訓練師{npc:198}在修道院樓上：從裡面的樓梯上去，箭頭無法區分樓層。",
		["{npc:248415}, by the Abbey"] = "{npc:248415}，在修道院旁",
		["{npc:251507} stands with the {area:87} trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the {area:64}, Gray Forest Wolves the woods east of {area:18}."] = "{npc:251507}和{area:87}的訓練師們站在一起。她的每個任務都會給你一根{item:15908}：對她指定的野獸使用，然後把馴獸棒帶回給她。石皮野豬和小森林熊在{area:64}南邊的山丘遊蕩，森林灰狼在{area:18}東邊的樹林裡。",
		["{npc:253}, back in the inn"] = "{npc:253}，回到旅店裡",
		["{npc:253}, inside"] = "{npc:253}，在裡面",
		["{npc:257446} in {zone:1426}; {area:87} has no shaman trainer"] = "{npc:257446}在{zone:1426}；{area:87}沒有薩滿訓練師",
		["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}，在她旁邊：{spell:5149}",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it."] = "{npc:261}守衛東邊道路上的橋；{npc:248265}就站在橋的另一頭。",
		["{npc:263399} camps north-east of the inn. With a profession learned, he also offers its Camping 101, which its trainer takes: skinning, leatherworking and fishing on the lake shore, {skill:129} and blacksmithing in {area:87}, herbalism and alchemy back in {area:24}, tailoring at the {area:88}, mining, engineering and enchanting in {zone:1453}."] = "{npc:263399}在旅店東北方紮營。學會一項專業後，他還會提供該專業的露營 101，由其訓練師接收：剝皮、製皮和釣魚在湖岸，{skill:129}和鍛造在{area:87}，草藥學和鍊金術回到{area:24}，裁縫在{area:88}，採礦、工程學和附魔在{zone:1453}。",
		["{npc:263399}: for {npc:11026} in {zone:1453}'s {object:28027}"] = "{npc:263399}：交給{zone:1453}{object:28027}的{npc:11026}",
		["{npc:263399}: for {npc:1103} at the {area:88}"] = "{npc:263399}：交給{area:88}的{npc:1103}",
		["{npc:263399}: for {npc:11068} in {zone:1453}"] = "{npc:263399}：交給{zone:1453}的{npc:11068}",
		["{npc:263399}: for {npc:1215} in {area:24}"] = "{npc:263399}：交給{area:24}的{npc:1215}",
		["{npc:263399}: for {npc:1218} in {area:24}"] = "{npc:263399}：交給{area:24}的{npc:1218}",
		["{npc:263399}: for {npc:1632} on the lake shore"] = "{npc:263399}：給湖岸邊的{npc:1632}",
		["{npc:263399}: for {npc:1651} on the lake shore"] = "{npc:263399}：給湖岸邊的{npc:1651}",
		["{npc:263399}: for {npc:2329} in the Lion's Pride Inn"] = "{npc:263399}：給獅王之傲旅店裡的{npc:2329}",
		["{npc:263399}: for {npc:514} at the {area:87} smithy"] = "{npc:263399}：給{area:87}鐵匠鋪的{npc:514}",
		["{npc:263399}: for {npc:5513} in {zone:1453}'s {object:28027}"] = "{npc:263399}：交給{zone:1453}{object:28027}的{npc:5513}",
		["{npc:263399}: for {npc:6306} on the lake shore"] = "{npc:263399}：給湖岸邊的{npc:6306}",
		["{npc:278}, inside"] = "{npc:278}，在裡面",
		["{npc:279} in {zone:1453} takes it (the {zone:1436} guide)"] = "{zone:1453}的{npc:279}接收它（{zone:1436}指南）",
		["{npc:295}, inside"] = "{npc:295}，在裡面",
		["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328}：由{zone:1453}的{npc:5497}接收",
		["{npc:375}, the priest trainer"] = "{npc:375}，牧師訓練師",
		["{npc:375}, the priest trainer: {npc:377} in {area:87} takes it"] = "{npc:375}，牧師訓練師：由{area:87}的{npc:377}接收",
		["{npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:377}（牧師）、{npc:328}（法師）和{npc:917}（盜賊）在旅店樓上：走室內樓梯上去，箭頭無法區分樓層。",
		["{npc:377}, upstairs"] = "{npc:377}，在樓上",
		["{npc:377}, upstairs: {item:16605}"] = "{npc:377}，在樓上：{item:16605}",
		["{npc:377}: heal {npc:12423} at {area:18}"] = "{npc:377}：在{area:18}治療{npc:12423}",
		["{npc:377}: {npc:376} in {zone:1453} takes it"] = "{npc:377}：由{zone:1453}的{npc:376}接收",
		["{npc:459}, outside the Abbey"] = "{npc:459}，在修道院外",
		["{npc:476} walks around {area:54}: look inside the circle on the map"] = "{npc:476}在{area:54}一帶走動：看地圖上的圓圈內部",
		["{npc:514} takes it once your {skill:164} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:164}技能達到20後，{npc:514}就會接收它：在那之前先採集或製作，指南會同時繼續進行。",
		["{npc:514}, at the smithy across the road"] = "{npc:514}，在路對面的鐵匠鋪",
		["{npc:514}, at the smithy beside Dughan: {npc:1416} in {zone:1453} takes it (the {zone:1436} guide)"] = "{npc:514}，在杜漢旁邊的鐵匠鋪：{zone:1453}的{npc:1416}接收它（{zone:1436}指南）",
		["{npc:524}: tame it with the {item:15908}"] = "{npc:524}：用{item:15908}馴服牠",
		["{npc:5504} in {zone:1453}; {area:87} has no druid trainer"] = "{npc:5504}在{zone:1453}；{area:87}沒有德魯伊訓練師",
		["{npc:5513} takes it once your {skill:186} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:186}技能達到20時，{npc:5513}會接收它：在此之前採集或製作，指南同時繼續進行。",
		["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121}：由{zone:1453}的{npc:6122}接收",
		["{npc:6306} takes it once your {skill:393} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:393}技能達到20後，{npc:6306}就會接收它：在那之前先採集或製作，指南會同時繼續進行。",
		["{npc:6306}, inside"] = "{npc:6306}，在裡面",
		["{npc:6306}, on the lake shore east of town; inside"] = "{npc:6306}，在鎮東的湖岸邊；在室內",
		["{npc:6306}, {npc:383} and {npc:1651} stand on the shore of {area:18} east of town."] = "{npc:6306}、{npc:383}和{npc:1651}站在鎮東{area:18}的岸邊。",
		["{npc:6306}: skinners only, the pelts are skinned; inside"] = "{npc:6306}：僅限剝皮者，毛皮需剝皮取得；在裡面",
		["{npc:6774}, by the stables south of the Abbey"] = "{npc:6774}，在修道院南邊的馬廄旁",
		["{npc:6} dig in the vineyards north-east of the Abbey. Now and then one drops a {quest:91741}: right-click it."] = "{npc:6}在修道院東北方的葡萄園挖掘。偶爾會掉落{quest:91741}：右鍵點擊它。",
		["{npc:80} walks around {area:34}: look inside the circle on the map"] = "{npc:80}在{area:34}一帶走動：看地圖上的圓圈內部",
		["{npc:822}: tame it with the {item:15908}"] = "{npc:822}：用{item:15908}馴服牠",
		["{npc:823}, at the Abbey steps"] = "{npc:823}，在修道院臺階處",
		["{npc:823}, back at the Abbey steps"] = "{npc:823}，回到修道院台階",
		["{npc:894} sells the Shiny Red Apples for the {quest:91736}. Apples looted from kobolds and crates count too: the purchase ticks itself once you have four."] = "{npc:894}出售{quest:91736}所需的閃光的紅蘋果。從狗頭人和箱子拾取的蘋果也算：湊夠四個後，購買目標會自動完成。",
		["{npc:911}, the warrior trainer; inside"] = "{npc:911}，戰士訓練師；在裡面",
		["{npc:915}, the rogue trainer"] = "{npc:915}，盜賊訓練師",
		["{npc:925}, the paladin trainer"] = "{npc:925}，聖騎士訓練師",
		["{npc:952}, upstairs"] = "{npc:952}，在樓上",
		["{npc:955}: he wants your {item:247824}; inside"] = "{npc:955}：他要你的{item:247824}；在裡面",
		["{npc:963}: for {npc:234} at {area:108}"] = "{npc:963}：給{area:108}的{npc:234}",
		["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood.\nStonetusk Boars graze between the vineyards and the farm."] = "{object:694855}生長在葡萄園和斯通菲爾德農場周圍的田野；附近的石牙野豬提供血液。\n石牙野豬在葡萄園和農場之間吃草。",
		["{quest:76}'s entrance"] = "{quest:76}入口",
		["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it.\nCareful: {npc:248464} (6), a kobold deep in the mine, is elite, and {npc:79} (10, rare) walks the tunnels: pull the kobolds one at a time."] = "{quest:87}在{area:57}裡面，不在上方的山丘上：從入口進去，靠左走到礦坑底層的最深處；不要走樓梯上去。葡萄園周圍的迪菲亞強盜偶爾會掉落{item:1972}：右鍵點擊它。\n小心：礦坑深處的狗頭人{npc:248464}（6級）是精英，{npc:79}（10級，稀有）在隧道裡遊蕩：一次拉一隻狗頭人。",
		["{quest:91733} and {npc:330}"] = "{quest:91733}與{npc:330}",
		["{zone:1429}: kill these as you meet them"] = "{zone:1429}：遇到就殺",
} end)()
t.guides["forever/alliance/nightelf/01-teldrassil"] = (function() return {
		["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "在{npc:265811}的營火旁/sit，直到獲得{spell:1229451}",
		["Back at {area:256}"] = "回到{area:256}",
		["Back out of the city gate and east along the road: {quest:1683} stands south of it, by {area:736}. Bring his horn back to {quest:1684}."] = "出城門後沿路向東：{quest:1683}站在路南、{area:736}旁。把他的號角帶回去交給{quest:1684}。",
		["Back to the moonwell."] = "回到月井。",
		["Back to the top of {area:256}. The {object:654846} lies beside him."] = "回到{area:256}頂端。{object:654846}就在他旁邊。",
		["Back upstairs to {npc:3567} with the webwoods done and {npc:272116}'s moss."] = "完成蜘蛛任務並帶著{npc:272116}的苔蘚，回到樓上找{npc:3567}。",
		["Befouled Webwoods"] = "被污染的樹林蜘蛛",
		["Below ground"] = "地下",
		["Bloodfeather harpies"] = "血羽鷹身人",
		["Cast {spell:18960}"] = "施放{spell:18960}",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Learn {area:493}'s flight path from {npc:10897}, south of the lake, for later trips. Then {npc:11800} in {area:2361} flies Druids straight to {area:702} from her gossip: hers is no flight path to learn. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "施放{spell:18960}。{npc:11802}在{area:2361}；{quest:5929}在西北方的樹林裡。順便向湖南邊的{npc:10897}學會{area:493}的飛行路線，方便以後往返。然後{area:2361}的{npc:11800}可透過對話直接把德魯伊送到{area:702}：她那裡沒有可學的飛行路線。{npc:11802}站在他建築的樓上：從裡面上樓，箭頭分不出樓層。",
		["Crawler Legs: the Tide Crawlers"] = "爬行者的腿：潮汐爬行者",
		["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "達札拉的每個任務都會給你一根{item:15908}：對他指定的野獸使用，然後把馴獸棒帶回{area:186}給他。樹林潛伏者在村莊周圍潛行，夜刃捕食者和巨翼惡梟在村莊南邊的樹林遊蕩。",
		["East along the road to {area:186}."] = "沿著道路向東前往{area:186}。",
		["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "護送{npc:275744}離開古墓；由{area:186}的{npc:2081}接收報告。",
		["Fandral in {zone:1457} takes it"] = "由{zone:1457}的范達爾接收",
		["Fel Cones lie under the trees all around {area:186} and {npc:2150}: pick them up on the road east and hand them to {npc:2150} on the way to {npc:7234}."] = "魔錐果散落在{area:186}和{npc:2150}周圍的樹下：在往東的路上撿起來，並在前往{npc:7234}的路上交給{npc:2150}。",
		["Fishers only: {npc:10216} stands on the pier. His {item:12238} is fished from the pier itself."] = "僅限釣魚者：{npc:10216}站在碼頭上。他的{item:12238}就在碼頭上釣得到。",
		["Fly back to {area:702} from {npc:3841}, hand {item:16263} to {npc:10118} on the dock, then fly back to {area:442}."] = "從{npc:3841}處飛回{area:702}，把{item:16263}交給碼頭上的{npc:10118}，然後飛回{area:442}。",
		["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442}."] = "再飛往{area:702}一次，搭傳送門上去找{npc:4217}，然後飛回{area:442}。",
		["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "沿著道路向西南離開{area:188}。{npc:2150}就坐在路旁，在{area:186}東邊不遠處。",
		["Gnarlpine Ambushers hide along the road west of {area:258}."] = "瘤背伏擊者埋伏在{area:258}西邊的道路沿線。",
		["Gnarlpine Mystics and {npc:7234} camp north-east of {area:260}. {npc:7234} drops the {item:8049}: open it for the jewel.\nCareful: {npc:7234} waits near the camp fire with mystics around him, so pulling him without adds is hard."] = "瘤背秘法師和{npc:7234}在{area:260}東北方紮營。{npc:7234}會掉落{item:8049}：打開它取得寶石。\n小心：{npc:7234}在營火旁等著，周圍有秘法師，很難單獨把他拉出來。",
		["Gnarlpine Shamans"] = "瘤背薩滿",
		["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "回到{area:702}，飛往{area:442}。{object:177525}在村莊東邊的山丘上：在那裡使用{item:15208}，擊敗月爪梟獸，然後與{npc:12144}交談。",
		["Grells"] = "小劣魔",
		["Grells (level 2-3) carry {item:3297} in the woods west of the tree, by the totems. The {npc:1989} further north are level 3-4: the Grells by the totems are enough."] = "小劣魔（2-3級）帶著{item:3297}，在樹西邊圖騰旁的樹林裡。更北邊的{npc:1989}是3-4級：圖騰旁的小劣魔就夠了。",
		["Heal and fortify {npc:12429}"] = "治療{npc:12429}並施放耐力",
		["Into the city through the gate. {quest:922} is just south of the {area:1658} at the north end, {npc:7316} in the west, {npc:7313} and {npc:8396} in the Temple of the Moon at the south end. On the way back out, use Dalia's {item:279378} at the bank and at the city gate; the other two owls wait for your last visit."] = "穿過大門進城。{quest:922}就在北端{area:1658}的南邊，{npc:7316}在西部，{npc:7313}和{npc:8396}在南端的月神殿。往回走的時候，在銀行和城門使用達莉婭的{item:279378}；另外兩隻貓頭鷹留到你最後一次來時再找。",
		["Lead {quest:938} to the moonwell"] = "把{quest:938}引到月井",
		["Learn the flight path from {npc:3841} where you land. {npc:4200}'s fish stall is just north of her, by the docks.\nThe boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "降落後先找{npc:3841}學習飛行路線。{npc:4200}的魚攤就在她北邊、碼頭旁。\n船停在村子西邊。飛行管理員站在旅店南邊的山丘上；任務釋出者分散在主街上。",
		["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "從{area:256}東南方的小路離開{area:188}：{npc:6780}站在路旁，就在小路往下通往{area:186}道路的地方。",
		["Level 12 spells while you're in the Temple of the Moon: the priest trainers stand beside {npc:11401}."] = "趁你在月神殿時學習12級法術：牧師訓練師站在{npc:11401}旁邊。",
		["Level 12 spells while you're in the {area:1658}: the hunter, rogue and druid trainers all stand in it."] = "趁你在{area:1658}時學習12級法術：獵人、盜賊和德魯伊訓練師都在裡面。",
		["Level 12 spells while you're on the {area:1660}: the warrior trainers stand beside {quest:1684}."] = "趁你在{area:1660}時學習12級法術：戰士訓練師站在{quest:1684}旁邊。",
		["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:1994} sits deep inside. {npc:8584} waits in the trees west of the cave mouth."] = "癩皮夜刃豹和草刺野豬在{area:256}北邊、前往洞穴的路上遊蕩。{npc:1994}在洞穴深處。{npc:8584}在洞口西邊的樹林裡等候。",
		["Nightsabers"] = "夜刃豹",
		["North to {area:257}"] = "向北前往{area:257}",
		["North-east from Ursal's den, back to {area:186}. {npc:6094} takes a {item:159} with the fronds and the vial: if you drank yours, buy another from {npc:6736} in this inn before you hand in."] = "從烏薩爾的巢穴往東北回到{area:186}。{npc:6094}要收一瓶{item:159}，連同葉子和小瓶：如果你把自己的喝掉了，繳交前先在這間旅店向{npc:6736}再買一瓶。",
		["North-west of Dolanaar, on the way to the {area:264}, Befouled Webwoods creep through the woods; {npc:272116} prowls at their east edge and carries the {item:281023}.\n{npc:272116} is elite (level 12): grouping up is advised. Clear the webwoods around him first and pull him on his own."] = "在多蘭納爾西北方、前往{area:264}的路上，被污染的樹林蜘蛛在樹林裡爬行；{npc:272116}在牠們的東緣徘徊，身上帶著{item:281023}。\n{npc:272116}是精英怪（12級）：建議組隊。先清掉他周圍的蜘蛛，再單獨把他拉出來。",
		["On the way back south to the glade: {npc:272046} (level 12) flies on the slopes north-west of the moonwell, among Bloodfeather Matriarchs (11). Pull the harpies around her first."] = "往南回林地的路上：{npc:272046}（12級）在月井西北方的山坡上飛行，周圍有血羽女王（11級）。先把她周圍的鳥身女妖拉掉。",
		["Portal to {quest:940}"] = "通往{quest:940}的傳送門",
		["Priest trainer"] = "牧師訓練師",
		["Sentinel Arynia again"] = "再次找哨兵阿瑞尼亞",
		["South from the glade to the road: Shayla walks the road west of {area:186}, from where the path down from the glade meets it south-west to the bend at about 38,54 and back."] = "從林地向南走到道路：夏伊拉在{area:186}西邊的道路上來回巡邏，從林地下來的小路與道路交會處往西南走到約38,54的彎道再折返。",
		["South of the pools. The {object:6751} grows by the Hold; the furbolgs around it drop the rest of the fangs.\nCareful: the Gnarlpine Avengers (9-10) and Augurs here stand close together and many players died at the Hold: pull them one at a time."] = "在池塘南邊。{object:6751}生長在脊骨堡旁；周圍的熊怪會掉落其餘的牙。\n小心：這裡的瘤背復仇者（9-10級）和先知站得很近，很多玩家都死在脊骨堡：一次拉一隻。",
		["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "從多蘭納爾向東南前往{npc:2080}那裡。鞭笞者幼苗在岸邊他的周圍遊蕩。",
		["South-west from {area:259}, past the {area:478}: Ursal prowls the far south of the island.\nCareful: Gnarlpine of roughly level 9-11 crowd the camp and sit close together, so it is easy to pull several at once. Take them on singly before you engage Ursal."] = "從{area:259}往西南走，經過{area:478}：烏薩爾在島的最南端徘徊。\n小心：營地裡擠滿了約9-11級的瘤背熊怪，而且站得很近，很容易一次引來好幾隻。先逐一解決牠們，再去打烏薩爾。",
		["South-west of Starbreeze, south of {npc:2150}. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "在星風村西南方，{npc:2150}南邊。{npc:2080}在岸邊照料他的樹苗；鞭笞者幼苗和林精在他周圍遊蕩，{quest:919}就生長在牠們之間。",
		["South-west of the barrow. The moonwell sits by the pools."] = "在古墓西南方。月井就在池塘旁。",
		["Speak with the {quest:5929}"] = "與{quest:5929}交談",
		["Take the antidote from {npc:8583} at the foot of {area:256} only now, on the way down: it lasts five minutes. {npc:8584} waits north-west, by the cave: go straight on to him."] = "現在才在下來時到{area:256}腳下找{npc:8583}拿解藥：它只能維持五分鐘。{npc:8584}在西北邊的洞穴旁等著：直接去找他。",
		["Take the portal down to {area:702}. {npc:10118} stands on the dock, {npc:3838} by the hippogryphs. Once you have {quest:6342}, talk to {npc:3838} again and choose the flight to {area:442}: it is free and lands beside {npc:4200}. If the flight map opens instead, close it and talk to him again holding Shift."] = "透過傳送門下到{area:702}。{npc:10118}站在碼頭上，{npc:3838}在角鷹獸旁。接到{quest:6342}後，再次與{npc:3838}交談，選擇飛往{area:442}：這趟免費，落地就在{npc:4200}旁邊。如果開啟的是飛行地圖，先關閉，再按住 Shift 與他交談。",
		["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "再次沿著道路從{area:186}向西北走；她仍躺在路旁，在前往{zone:1457}的路上。",
		["The Bloodfeather harpies nest on the slopes west and north of the glade. {quest:938}, an injured sabercat, lies by the glade's west wall among them: lead her back to Sentinel Arynia at the moonwell before her time runs out.\nCareful: The harpies stand packed together, so extra ones often join a fight. Casters are mixed in among them."] = "血羽鷹身人在林間空地以西和以北的山坡築巢。{quest:938}是一隻受傷的刃豹，躺在它們中間、林間空地的西牆旁：趕在時間耗盡前把她帶回月井旁的哨兵艾瑞尼婭那裡。\n注意：鷹身人站得很密集，所以常會有額外的加入戰鬥。施法者混在它們中間。",
		["The WANTED poster outside the inn"] = "旅店外的通緝海報",
		["The barrow is south of the road. {npc:275744} is held inside, {npc:7317} sleeps in its depths, and the four relic chests sit in the lower rooms. Its furbolgs drop Shayla's fangs.\nCareful: the barrow's Gnarlpine Defenders, Augurs and Shamans (7-9) stand in threes in the narrow tunnels: pull each group back toward the entrance before you go deeper."] = "古墓在道路南邊。{npc:275744}被關在裡面，{npc:7317}在深處沉睡，四個聖物箱在下層的房間裡。裡面的熊怪會掉落夏伊拉要的牙。\n小心：古墓裡的瘤背防禦者、預言者和薩滿（7-9級）三個一組站在狹窄的隧道裡：深入之前，先把每一組拉回入口方向。",
		["The grells west of the tree"] = "樹西邊的小劣魔",
		["The moonwell"] = "月井",
		["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "月井在林地中央。{object:6752}生長在林地北端。",
		["The moonwell sits north of {area:256}."] = "月亮井位於{area:256}以北。",
		["The road to {zone:1457}"] = "前往{zone:1457}的道路",
		["The road west to the {area:264} runs through {area:186}: hand {npc:3567} the jewel on the way."] = "往西去{area:264}的路穿過{area:186}：順路把寶石交給{npc:3567}。",
		["The trainers stand upstairs inside {area:256}, along the ramp that winds up the tree: {npc:3593} and {npc:3594} on the first level, {npc:3595} above them, {npc:3596} and {npc:3597} at the top. The arrow cannot tell the levels apart."] = "訓練師們站在{area:256}內的樓上，沿繞著樹幹盤旋而上的坡道分佈：{npc:3593}和{npc:3594}在第一層，{npc:3595}在他們上方，{npc:3596}和{npc:3597}在頂層。箭頭分不清樓層。",
		["The {area:265}"] = "{area:265}",
		["The {area:478}"] = "{area:478}",
		["The {object:177525}"] = "{object:177525}",
		["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "{object:4406}在{area:257}深處：走中間的路，分岔處往左，一路上到高處的岩架。紫藍色蘑菇由小劣魔掉落，月牙百合花生長在{area:256}北邊的池塘旁。",
		["The {object:6752} grows at the glade's north end, on the way: then north along the island's northern edge by {area:266}, {npc:7319}, a level 12 spider, lurks."] = "{object:6752}生長在林地北端，順路採：然後沿著島的北緣往北到{area:266}旁，12級蜘蛛{npc:7319}潛伏在那裡。",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "潮行蟹在村子下方的海岸爬行；{quest:983}站在碼頭南邊不遠的海灘上。黑海岸蛇頸龍在淺水中游動。{object:175207}在村子南邊不遠的岸上。",
		["Upstairs"] = "樓上",
		["Use the {item:18152} at the moonwell"] = "在月井使用{item:18152}",
		["Use the {item:5185} at the moonwell"] = "在月井使用{item:5185}",
		["Use the {item:5619} at the moonwell"] = "在月井使用{item:5619}",
		["Use the {item:5621} at the moonwell"] = "在月井使用{item:5621}",
		["Walk Lynessa out and keep her alive"] = "護送哨兵離開，並保住她的性命",
		["Warrior trainer"] = "戰士訓練師",
		["Webwood Lurkers"] = "樹林潛伏者",
		["Webwood Spiders; below ground"] = "蛛網蜘蛛；地下",
		["West along the road toward the city. Shayla walks this stretch of road, from the arrow south-west to the bend at about 38,54 and back: if she isn't at the arrow, follow the road south-west. Every Gnarlpine furbolg drops fangs: the ambushers on this road, the barrow's and {area:261}'s all count."] = "沿著道路向西朝城市前進。夏伊拉在這段路上來回巡邏，從箭頭處往西南走到約38,54的彎道再折返：如果她不在箭頭處，沿著道路往西南走。每個瘤背熊怪都會掉落牙齒：這條路上的伏擊者、古墓裡的以及{area:261}的都算數。",
		["West from the webwoods to the {area:265}, then north along it to the glade: the timberlings along its banks drop the Mossy Tumors.\nCareful: {npc:272116}, a level 12 elite, prowls the east edge of the Befouled Webwoods north-west of {area:186}: if you are alone, keep clear of the webwoods and go round him."] = "從蜘蛛所在的樹林往西到{area:265}，再沿著河往北到林地：河岸邊的樹人會掉落青苔之瘤。\n小心：12級精英{npc:272116}在{area:186}西北方被污染的樹林蜘蛛的東緣徘徊：如果你是單人，就遠離那些蜘蛛，繞過他。",
		["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "順路：向{npc:11866}（{area:1660}，10銀）學習法杖；獵人的近戰武器主要看屬性，雙手武器提供的屬性最多。",
		["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "順路：向{npc:11866}（{area:1660}，10銀）學習法杖；升級期間法杖提供的法術屬性比單手武器多。",
		["With a profession learned, {npc:265811} also offers its Camping 101, which its trainer takes: alchemy and herbalism beside {npc:6286}, {skill:129} with {npc:6094} in the inn, skinning and leatherworking at the Maneweavers' camp on the road west, fishing and tailoring in {zone:1457}, enchanting north of the city, blacksmithing, mining and engineering in {area:442}."] = "學會一項專業後，{npc:265811}還會提供該專業的露營 101，由其訓練師接收：鍊金術和草藥學在{npc:6286}旁邊，{skill:129}找旅店裡的{npc:6094}，剝皮和製皮在西邊路上的鬃織營地，釣魚和裁縫在{zone:1457}，附魔在城市北邊，鍛造、採礦和工程學在{area:442}。",
		["You start at the foot of {area:256}, the great tree of {area:188}."] = "你從{area:188}的巨樹{area:256}底下開始。",
		["Young Nightsabers and Young Thistle Boars (level 1-2) roam around {area:256}: start with them. The Gnarlpine Totems stand in the woods west of the tree, where the Grells (2-3) roam: take them once the beasts are done."] = "小夜刃豹和小草刺野豬（1-2級）在{area:256}周圍遊蕩：先打牠們。瘤背圖騰矗立在樹西邊的樹林裡，小劣魔（2-3級）在那裡遊蕩：野獸打完後再去處理。",
		["talk to the trainer"] = "與訓練師交談",
		["talk to {npc:3838} again: free with {quest:6342}"] = "再次與{npc:3838}交談：持有{quest:6342}時免費",
		["the city gate"] = "城門",
		["the same {object:673378}: Fandral in {zone:1457} takes it"] = "同一個{object:673378}：{zone:1457}的範達爾會收下它",
		["the tunnel mouth below {area:3425}, on the way south"] = "{area:3425}下方的隧道口，在南下的路上",
		["{area:1658} trainers"] = "{area:1658}訓練師",
		["{area:186} again"] = "再次回到{area:186}",
		["{area:188}: kill these as you meet them"] = "{area:188}：遇到就殺",
		["{area:258}'s mouth"] = "{area:258}入口",
		["{area:262}'s entrance"] = "{area:262}的入口",
		["{area:442} flight master"] = "{area:442}飛行管理員",
		["{area:702} flight master"] = "{area:702}飛行管理員",
		["{area:736}, outside the barrow"] = "{area:736}，在古墓外",
		["{item:159} from {npc:6736}, for {npc:6094}"] = "向{npc:6736}購買{item:159}，給{npc:6094}",
		["{item:279378}: the bank, on the way out"] = "{item:279378}：銀行，出去時順路",
		["{item:279378}: the inn on the {area:1659}"] = "{item:279378}：{area:1659}上的旅店",
		["{item:3371} from {npc:3614}, beside {npc:6094}"] = "向{npc:6094}旁邊的{npc:3614}購買{item:3371}",
		["{item:5170}: timberlings"] = "{item:5170}：樹精",
		["{item:5220}: any Gnarlpine furbolg"] = "{item:5220}：任意一隻瘤背熊怪",
		["{item:8049}, from {npc:7234}"] = "{item:8049}，來自{npc:7234}",
		["{npc:10118} stands on the Rut'theran dock where you land. Then take the portal up to {npc:4217} in the {area:1658}."] = "落地後，{npc:10118}就在魯瑟蘭村碼頭上。隨後透過傳送門上去，到{area:1658}找{npc:4217}。",
		["{npc:10216}, on the pier"] = "{npc:10216}，在碼頭上",
		["{npc:11037} takes it once your {skill:202} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:202}技能達到20時，{npc:11037}會接收它：在此之前採集或製作，指南同時繼續進行。",
		["{npc:11050} takes it once your {skill:197} skill is 20: gather or craft until then, the guide carries on meanwhile."] = "你的{skill:197}技能達到20時，{npc:11050}會接收它：在此之前採集或製作，指南同時繼續進行。",
		["{npc:11401}, in the Temple of the Moon: Starshards"] = "{npc:11401}，在月神殿裡：星辰碎片",
		["{npc:12429} kneels wounded on the rocks at the north edge of {area:259}, on the walk back to {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count. She runs off once both land and is back in about 5 minutes."] = "{npc:12429}受傷跪在{area:259}北緣的岩石上，就在走回{area:186}的路上，她頭上沒有任務標記。對她施放{spell:613}（等級2），然後施放{spell:1243}：等級1的{spell:613}不算數。兩個法術都生效後她就會跑開，約5分鐘後回來。",
		["{npc:1992}, south of the tree"] = "{npc:1992}，在樹的南邊",
		["{npc:1996}: tame it with the {item:15908}"] = "{npc:1996}：用{item:15908}馴服牠",
		["{npc:1998}: tame it with the {item:15908}"] = "{npc:1998}：用{item:15908}馴服牠",
		["{npc:2038} waits inside the cave, at the bottom or up on the ledge; keep to the right."] = "{npc:2038}在洞穴裡等候，在底部或上方的岩架上；靠右走。",
		["{npc:2038}; below ground"] = "{npc:2038}；地下",
		["{npc:2043}: tame it with the {item:15908}"] = "{npc:2043}：用{item:15908}馴服牠",
