} end)()
t.guides["forever/professions/enchanting"] = (function() return {
		["1 {item:11082} for {item:11130}: {skill:333}: disenchant green items of item level 16-25."] = "準備1個{item:11082}製作{item:11130}：{skill:333}：分解物品等級16-25的綠色物品。",
