		["{faction:2799} to Friendly"] = "{faction:2799}到友善",
		["{faction:2799} to Honored"] = "{faction:2799}到尊敬",
		["{faction:2799} to Revered"] = "{faction:2799}到崇敬",
		["{npc:15350}: 100 for 3 marks"] = "{npc:15350}：3枚徽記換100",
		["{npc:15350}: {quest:98887} again, 100 for 3 marks"] = "{npc:15350}：再次{quest:98887}，3枚徽記換100",
		["{npc:15351}: 100 for 3 marks"] = "{npc:15351}：3枚徽記換100",
		["{npc:15351}: {quest:98895} again, 100 for 3 marks"] = "{npc:15351}：再次{quest:98895}，3枚徽記換100",
